.ua-order { color-scheme:dark; --navy:#0b1c2d; --panel:#13283d; --gold:#e8c87d; color:#f4f5f7; background:var(--navy); font:16px/1.5 system-ui,sans-serif; max-width:1120px; margin:auto; padding:24px; border-radius:16px; }
.ua-order *, .ua-order *::before, .ua-order *::after { box-sizing:border-box; }
.ua-order [hidden] { display:none !important; }
.ua-order button, .ua-order .button { font:inherit; cursor:pointer; min-height:44px; border:1px solid var(--gold); border-radius:9px; background:var(--gold); color:#0b1c2d; padding:10px 18px; font-weight:650; text-decoration:none; text-align:center; }
.ua-order button:disabled { cursor:wait; opacity:.65; }
.ua-order .secondary { background:transparent; color:#f4f5f7; border-color:#728292; }
.ua-order #other-model { display:block; margin:0 auto 18px; }
.ua-order :focus-visible { outline:3px solid #fff; outline-offset:3px; }
.ua-order a { color:inherit; }
.ua-order h1 { font-size:clamp(28px,4vw,42px); line-height:1.15; margin:34px 0 20px; }
.ua-order h2 { font-size:22px; margin:26px 0 18px; }
.ua-order #message:empty { display:none; }
.ua-order #message { color:var(--gold); }
.ua-order .country-grid { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:12px; }
.ua-order .country { display:flex; min-height:110px; flex-direction:column; align-items:center; justify-content:center; gap:10px; padding:12px 4px; border:1px solid #486074; border-radius:10px; text-decoration:none; background:var(--panel); overflow-wrap:anywhere; font-size:15px; text-align:center; }
.ua-order .country[aria-current="true"] { border:2px solid var(--gold); color:var(--gold); }
.ua-order .country img { display:block; width:54px; height:36px; object-fit:contain; }
.ua-order .models { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:16px; margin-bottom:18px; }
.ua-order .model { background:var(--panel); border:1px solid #3c5367; border-radius:12px; overflow:hidden; display:flex; flex-direction:column; }
.ua-order .model-media { aspect-ratio:8/5; background:#243b4e; display:grid; place-items:center; color:#c4d1db; text-align:center; overflow:hidden; }
.ua-order .model-media img { width:100%; height:100%; object-fit:cover; }
.ua-order .model-info { padding:18px; display:flex; flex:1; flex-direction:column; gap:10px; }
.ua-order .model h3 { font-size:18px; line-height:1.35; margin:0; }
.ua-order .model .tag { font-size:13px; color:#d0dbe3; }
.ua-order .model button { margin-top:auto; width:100%; }
.ua-order form, .ua-order #review, .ua-order #receipt { margin-top:28px; padding:24px; background:var(--panel); border:1px solid #3c5367; border-radius:12px; overflow-wrap:anywhere; }
.ua-order .form-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:16px; }
.ua-order label { display:flex; flex-direction:column; gap:7px; margin-bottom:16px; }
.ua-order input, .ua-order select, .ua-order textarea { font:inherit; width:100%; min-width:0; max-width:100%; padding:12px; background:#0b1c2d; color:#fff; border:1px solid #728292; border-radius:8px; min-height:44px; }
.ua-order .consent { flex-direction:row; align-items:flex-start; }
.ua-order .consent input { width:22px; min-height:22px; height:22px; flex-shrink:0; }
.ua-order #consent-copy { font-size:14px; color:#c6d2dc; }
.ua-order .selection { color:var(--gold); font-weight:650; }
.ua-order .actions { display:flex; flex-wrap:wrap; gap:12px; }
.ua-order dl { display:grid; grid-template-columns:1fr 2fr; gap:8px 20px; }
.ua-order dt { color:#c6d2dc; }.ua-order dd { margin:0; overflow-wrap:anywhere; white-space:pre-wrap; }
@media(max-width:640px) {
 .ua-order { padding:16px; border-radius:0; }
 .ua-order .country-grid { gap:7px; }
 .ua-order .country { font-size:12px; min-height:100px; }
 .ua-order .country img { width:44px; height:30px; }
 .ua-order .models { grid-template-columns:1fr; gap:12px; }
 .ua-order .model { flex-direction:row; }
 .ua-order .model-media { width:42%; flex-shrink:0; aspect-ratio:auto; min-height:174px; }
 .ua-order .model-info { padding:12px; }
 .ua-order .model h3 { font-size:16px; }
 .ua-order .model button { padding:9px; }
 .ua-order .form-grid { grid-template-columns:1fr; gap:0; }
 .ua-order form, .ua-order #review, .ua-order #receipt { padding:16px; }
 .ua-order dl { grid-template-columns:1fr; gap:2px; }
 .ua-order dd { margin-bottom:12px; }
}
/* Preference controls stay scoped to this form; native selects keep mobile UX. */
.ua-order fieldset{margin:0;padding:16px;border:1px solid #516678;border-radius:12px;min-width:0}
.ua-order legend{padding:0 6px;max-width:100%;font-weight:650;color:var(--gold)}
.ua-order .field-help{font-size:14px;line-height:1.5;color:#c2ced8;margin:8px 0 12px}
.ua-order .field-error{font-size:15px;color:#ffb4ab;margin:8px 0 0}
.ua-order [aria-invalid=true]{border-color:#ffb4ab;outline:2px solid #ffb4ab}
.ua-order .control{margin-top:12px}
.ua-order .control label{margin:0 0 6px}
.ua-order .number-choice{display:grid;grid-template-columns:minmax(0,1fr);gap:8px}
.ua-order .range-controls{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
.ua-order .range-controls>div{min-width:0}
.ua-order .range-controls>div>span{display:block;margin:0 0 6px;color:#c2ced8}
.ua-order .check-option{display:flex;flex-direction:row;align-items:center;gap:10px;min-height:44px;margin:4px 0;font-size:15px;cursor:pointer}
.ua-order .check-option input{width:22px;height:22px;min-height:22px;flex:0 0 22px;accent-color:#e8c87d;padding:0}
.ua-order .colour-swatch{width:22px;height:22px;flex:0 0 22px;border:1px solid #b8c8d6;border-radius:4px}
.ua-order .visually-hidden{position:absolute;width:1px;height:1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap;border:0}
.ua-order fieldset>.check-option:last-of-type{margin-top:12px;color:#d5dce4}
.ua-order .choice-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:4px 12px}
.ua-order .model-choices{display:grid;gap:8px;margin:8px 0 12px}
.ua-order .model-choice{display:flex;align-items:center;gap:8px;min-width:0}
.ua-order .model-choice select{flex:1}
.ua-order .model-choice button{flex:0 0 44px;padding:8px}
.ua-order details{margin:22px 0;padding:16px;border:1px solid #516678;border-radius:12px}
.ua-order summary{cursor:pointer;min-height:44px;align-content:center;font-size:20px;font-weight:600}
.ua-order details[open] summary{margin-bottom:12px}
.ua-order textarea{resize:vertical}
.ua-order #optional-fields>fieldset:last-child{grid-column:1/-1}
.ua-order #main-fields{align-items:start;gap:16px}
.ua-order #optional-fields{gap:16px}
@media(max-width:600px){
 .ua-order fieldset{padding:12px}
 .ua-order details{padding:12px}
 .ua-order .range-controls,.ua-order .choice-grid{grid-template-columns:minmax(0,1fr)}
}

video/order/quick-lead.css.source:
.ua-quick{margin:18px 0 26px;padding:18px 16px;border:1px solid rgba(240,166,60,.45);border-radius:16px;background:#0f2137;color:#e8eef8}
.ua-quick h2{margin:0 0 12px;font-size:20px}
.ua-quick label{display:block;margin:0 0 12px;font-size:14px;color:#aebed0}
.ua-quick input{display:block;box-sizing:border-box;width:100%;margin-top:6px;padding:13px 14px;border:1px solid #728292;border-radius:12px;background:#0B1524;color:#e8eef8;font-size:17px}
.ua-quick button{display:block;width:100%;padding:15px 16px;border:0;border-radius:14px;background:#f0a63c;color:#10161f;font-weight:800;font-size:17px;cursor:pointer}
.ua-quick button:disabled{opacity:.6}
.ua-quick .note{margin:10px 0 0;font-size:14px;color:#e8eef8}
.ua-quick .consent{margin:8px 0 0;font-size:12px;line-height:1.4;color:#aebed0}
.ua-quick .privacy{display:inline-block;margin:6px 0 0;font-size:12px;color:#aebed0}
.ua-quick .status{margin:12px 0 0;font-weight:700}
.ua-quick-dialog{width:calc(100% - 32px);max-width:480px;padding:0;border:0;background:transparent}
.ua-quick-dialog::backdrop{background:rgba(5,10,18,.75)}
.ua-quick-dialog .ua-quick{margin:0}
.ua-quick .ua-quick-close{margin-top:12px;padding:11px 16px;background:transparent;color:#e8eef8;border:1px solid #728292;font-weight:650;font-size:15px}
.ua-order .model .quick-offer{background:transparent;color:#f0a63c;border-color:#f0a63c}
.ua-order .model .quick-offer+button{margin-top:0}
